import {
  bigint,
  boolean,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  serial,
  smallint,
  text,
  timestamp,
} from "drizzle-orm/pg-core";
import type { AspectRatio, CostKind, MediaKind, PaidBy, PaidPlanId, ProviderId, Source, SubscriptionProvider, TaskSchedule, UsageKind } from "@/lib/types";

// ---------- Better Auth tables (generated by its Drizzle schema generator) ----------

export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").default(false).notNull(),
  image: text("image"),
  /** A guest chatting without an account (better-auth's anonymous plugin). */
  isAnonymous: boolean("is_anonymous").default(false),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
});

export const session = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expires_at").notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (t) => [index("session_userId_idx").on(t.userId)],
);

export const account = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (t) => [index("account_userId_idx").on(t.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (t) => [index("verification_identifier_idx").on(t.identifier)],
);

export const rateLimit = pgTable("rate_limit", {
  id: text("id").primaryKey(),
  key: text("key").notNull().unique(),
  count: integer("count").notNull(),
  lastRequest: bigint("last_request", { mode: "number" }).notNull(),
});

// ---------- Application tables ----------

/** A file kept in storage (Vercel Blob or the local .data folder). */
export interface StoredFile {
  key: string;
  mime: string;
  name?: string;
  /** Documents: where the extracted text is stored, and its length. */
  textKey?: string;
  chars?: number;
  /** For MARYX only, not shown in the chat (a video's frames on one sheet). */
  hidden?: boolean;
}

export const chat = pgTable(
  "chat",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    provider: text("provider").$type<ProviderId>().notNull(),
    model: text("model").notNull(),
    assistantId: text("assistant_id"),
    /** «Временный чат»: not in the history or MARYX's memory; deleted when left (or after a day). */
    temporary: boolean("temporary").default(false).notNull(),
    /** A long chat's start, retold by MARYX for itself once it no longer fits the context. */
    summary: text("summary"),
    /** The last message (its seq) the summary covers. */
    summarySeq: integer("summary_seq"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
  },
  (t) => [index("chat_user_updated_idx").on(t.userId, t.updatedAt)],
);

export const message = pgTable(
  "message",
  {
    id: text("id").primaryKey(),
    // Insertion order; timestamps can tie within a millisecond.
    seq: serial("seq").notNull(),
    chatId: text("chat_id")
      .notNull()
      .references(() => chat.id, { onDelete: "cascade" }),
    role: text("role").$type<"user" | "assistant">().notNull(),
    content: text("content").notNull(),
    reasoning: text("reasoning"),
    attachments: jsonb("attachments").$type<StoredFile[]>(),
    provider: text("provider").$type<ProviderId>(),
    model: text("model"),
    error: text("error"),
    /** The provider's own reason for a failure, shown to admins only (users see `error`). */
    errorDetail: text("error_detail"),
    notice: text("notice"),
    /** Web pages the answer cites (web search). */
    sources: jsonb("sources").$type<Source[]>(),
    /** "maryx" when MARYX picked the model that wrote this answer. */
    via: text("via").$type<"maryx">(),
    /** Follow-up questions MARYX suggested after this answer. */
    suggestions: jsonb("suggestions").$type<string[]>(),
    /** A video answer: its gallery item (made in the background, also shown in the video studio). */
    mediaId: text("media_id"),
    /** The user's verdict on an answer: 1 👍, -1 👎. */
    rating: smallint("rating"),
    /** What was wrong, for a 👎 (one of RATING_REASONS). */
    ratingReason: text("rating_reason"),
    ratedAt: timestamp("rated_at"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("message_chat_seq_idx").on(t.chatId, t.seq), index("message_rated_idx").on(t.ratedAt)],
);

/** A page made in the chat (a game, a site) shared by a public link: /s/<id>. */
export const share = pgTable(
  "share",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    html: text("html").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("share_user_created_idx").on(t.userId, t.createdAt)],
);

/** «Задачи»: a prompt MARYX runs on a schedule by itself; each run's answer goes to the task's chat. */
export const task = pgTable(
  "task",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    prompt: text("prompt").notNull(),
    schedule: jsonb("schedule").$type<TaskSchedule>().notNull(),
    /** The user's IANA time zone, which the schedule's times are in. */
    timezone: text("timezone").notNull(),
    /** Searches the web on each run (news, prices, mentions). */
    search: boolean("search").default(false).notNull(),
    active: boolean("active").default(true).notNull(),
    nextRunAt: timestamp("next_run_at"),
    lastRunAt: timestamp("last_run_at"),
    lastStatus: text("last_status").$type<"ok" | "error" | "limit">(),
    lastError: text("last_error"),
    runs: integer("runs").default(0).notNull(),
    /** A result not seen yet (cleared when the task list is opened). */
    unread: boolean("unread").default(false).notNull(),
    /** Where the results go: a chat of its own. */
    chatId: text("chat_id"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("task_user_idx").on(t.userId, t.createdAt), index("task_due_idx").on(t.active, t.nextRunAt)],
);

/** «Мой персонаж»: 1–3 photos of one person MARYX draws in new scenes (a photoshoot). */
export const character = pgTable(
  "character",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    photos: jsonb("photos").$type<StoredFile[]>().notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("character_user_idx").on(t.userId, t.createdAt)],
);

export const assistant = pgTable(
  "assistant",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    emoji: text("emoji").notNull(),
    description: text("description").notNull(),
    systemPrompt: text("system_prompt").notNull(),
    provider: text("provider").$type<ProviderId>(),
    model: text("model"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("assistant_user_idx").on(t.userId)],
);

export const media = pgTable(
  "media",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    kind: text("kind").$type<MediaKind>().notNull(),
    prompt: text("prompt").notNull(),
    provider: text("provider").$type<ProviderId>().notNull(),
    model: text("model").notNull(),
    aspectRatio: text("aspect_ratio").$type<AspectRatio>().notNull(),
    status: text("status").$type<"pending" | "succeeded" | "failed">().notNull(),
    jobId: text("job_id"),
    progress: integer("progress"),
    error: text("error"),
    /** The provider's own reason for a failure, shown to admins only (users see `error`). */
    errorDetail: text("error_detail"),
    /** The user picked the model by hand (the video section's list): it's shown by its name, not as MARYX's. */
    chosen: boolean("chosen").default(false).notNull(),
    files: jsonb("files").$type<StoredFile[]>().default([]).notNull(),
    /** The user's photos it was made from (photo editing); deleted with the item. */
    inputs: jsonb("inputs").$type<StoredFile[]>(),
    /** The character it was drawn with («Мой персонаж»), to repeat it; kept when the character is deleted. */
    characterId: text("character_id"),
    /** Video: the camera move, effect and length it was asked with (to show them and to do it again). */
    settings: jsonb("settings").$type<{ camera?: string; effect?: string; duration?: number }>(),
    /** How the generation is paid for (null for items made before credits existed: the plan). */
    paidBy: text("paid_by").$type<PaidBy>(),
    /** Credits held when it started (paid with credits). */
    heldCredits: integer("held_credits").default(0).notNull(),
    /** The charge's id: its reserved cost sits in ai_cost under this id until the job ends. */
    chargeId: text("charge_id"),
    /** UTC day (YYYY-MM-DD) the use was counted on, so a refund gives it back on that day. */
    chargeDay: text("charge_day"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
  },
  (t) => [index("media_user_kind_idx").on(t.userId, t.kind, t.createdAt)],
);

/** Facts MARYX remembers about a user, shown and editable in settings. */
export const memory = pgTable(
  "memory",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    text: text("text").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("memory_user_idx").on(t.userId, t.createdAt)],
);

/** Per-user preferences. */
export const userPref = pgTable("user_pref", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  /** Let MARYX remember facts about the user. */
  memory: boolean("memory").default(true).notNull(),
  /** Personal instructions: what the user tells about themselves… */
  about: text("about"),
  /** …and how they want answers to look. Both go into every chat's system prompt. */
  style: text("style"),
  /** «Плагины» the user has on (null: the default set). */
  plugins: text("plugins").array(),
});

/** Daily counters for the free-tier limits. */
export const usage = pgTable(
  "usage",
  {
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    /** UTC date, YYYY-MM-DD. */
    day: text("day").notNull(),
    kind: text("kind").$type<UsageKind>().notNull(),
    count: integer("count").default(0).notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.day, t.kind] })],
);

// ---------- Billing ----------

/** One row per user that has ever paid. Access is granted while the period runs. */
export const subscription = pgTable("subscription", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  /** The paid plan: "plus" | "pro" | "ultra" (YooKassa and promo codes: Pro). */
  plan: text("plan").$type<PaidPlanId>().notNull(),
  /** Stripe and Paddle renew on their own; PayPal and TON pay for one month at a time. */
  provider: text("provider").$type<SubscriptionProvider>().notNull(),
  /** Stripe's or Paddle's status, or ours ("active" | "past_due" | "canceled"). */
  status: text("status").notNull(),
  currentPeriodEnd: timestamp("current_period_end").notNull(),
  cancelAtPeriodEnd: boolean("cancel_at_period_end").default(false).notNull(),
  stripeCustomerId: text("stripe_customer_id"),
  stripeSubscriptionId: text("stripe_subscription_id").unique(),
  /** Saved card for YooKassa autopayments. */
  yookassaPaymentMethodId: text("yookassa_payment_method_id"),
  paddleCustomerId: text("paddle_customer_id"),
  paddleSubscriptionId: text("paddle_subscription_id").unique(),
  /** Day of month the paid periods end on, so Jan 31 → Feb 28 → Mar 31. */
  anchorDay: integer("anchor_day"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

/** YooKassa payments we created (first payments and renewals). */
export const payment = pgTable(
  "payment",
  {
    /** YooKassa payment id. */
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    kind: text("kind").$type<"initial" | "renewal" | "credits">().notNull(),
    /** Credits bought with this payment (kind "credits"). */
    credits: integer("credits"),
    status: text("status").notNull(),
    amount: text("amount").notNull(),
    currency: text("currency").notNull(),
    /** Set once the payment has extended the subscription (idempotency). */
    appliedAt: timestamp("applied_at"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("payment_user_idx").on(t.userId, t.createdAt)],
);

/**
 * One-off purchases through PayPal or TON: a month of a plan or a pack of
 * credits. Created when checkout starts; applied once, when the money is in.
 */
export const purchase = pgTable(
  "purchase",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    provider: text("provider").$type<"paypal" | "ton">().notNull(),
    kind: text("kind").$type<"plan" | "credits">().notNull(),
    plan: text("plan").$type<PaidPlanId>(),
    credits: integer("credits"),
    /** The price in US dollars ("9.99"). */
    usd: text("usd").notNull(),
    /** What the provider is asked for: US dollars (PayPal) or nanotons (TON). */
    amount: text("amount").notNull(),
    currency: text("currency").$type<"USD" | "TON">().notNull(),
    /** TON: the comment the transfer must carry. */
    code: text("code").unique(),
    /** PayPal's order id, or the TON transaction's hash once paid. */
    externalId: text("external_id").unique(),
    status: text("status").$type<"pending" | "paid" | "failed" | "expired">().notNull(),
    /** Set once the purchase has been applied (idempotency). */
    appliedAt: timestamp("applied_at"),
    /** TON: the rate is held until then (a transfer arriving later is still taken for a day). */
    expiresAt: timestamp("expires_at"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("purchase_user_idx").on(t.userId, t.createdAt), index("purchase_pending_idx").on(t.provider, t.status)],
);

/** Codes an admin hands out; each grants Pro for a number of days and/or credits. */
export const promoCode = pgTable("promo_code", {
  code: text("code").primaryKey(),
  /** Days of Pro (0 when the code only gives credits). */
  days: integer("days").notNull(),
  /** AI credits the code gives. */
  credits: integer("credits").default(0).notNull(),
  maxUses: integer("max_uses").notNull(),
  uses: integer("uses").default(0).notNull(),
  note: text("note"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

export const promoRedemption = pgTable(
  "promo_redemption",
  {
    code: text("code")
      .notNull()
      .references(() => promoCode.code, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [primaryKey({ columns: [t.code, t.userId] })],
);

/**
 * A YooKassa renewal charge we are about to make, written before the API call.
 * If the server dies mid-call, the next run reuses the same Idempotence-Key,
 * so YooKassa returns the original payment instead of charging twice.
 */
export const renewalAttempt = pgTable(
  "renewal_attempt",
  {
    /** Also the Idempotence-Key sent to YooKassa. */
    key: text("key").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    /** End of the period being renewed. */
    periodEnd: timestamp("period_end").notNull(),
    /** Filled once YooKassa answered. */
    paymentId: text("payment_id"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("renewal_attempt_user_idx").on(t.userId, t.periodEnd)],
);

// ---------- AI costs and credits ----------

/**
 * What every AI request cost: one row per model call made with the server's
 * keys or with a user's own key. Kept when the user is deleted, for the totals.
 */
export const aiCost = pgTable(
  "ai_cost",
  {
    id: text("id").primaryKey(),
    userId: text("user_id").references(() => user.id, { onDelete: "set null" }),
    at: timestamp("at").defaultNow().notNull(),
    kind: text("kind").$type<CostKind>().notNull(),
    provider: text("provider").notNull(),
    model: text("model").notNull(),
    inputTokens: integer("input_tokens"),
    outputTokens: integer("output_tokens"),
    /** US dollars, as reported by the provider or estimated from list prices. */
    costUsd: doublePrecision("cost_usd").notNull(),
    /** The provider didn't report the cost; it was worked out from tokens and list prices. */
    estimated: boolean("estimated").default(false).notNull(),
    paidBy: text("paid_by").$type<PaidBy>().notNull(),
    /** Credits taken from the user's balance for this request. */
    credits: integer("credits").default(0).notNull(),
    /**
     * A request still running: its estimated cost counts toward the budgets
     * until the real cost replaces it. One left behind (the server was killed
     * mid-answer) stays as the estimate.
     */
    pending: boolean("pending").default(false).notNull(),
  },
  (t) => [index("ai_cost_at_idx").on(t.at), index("ai_cost_user_idx").on(t.userId, t.at)],
);

/** Prepaid AI credits, spent once the plan's daily limits are used up. */
export const creditBalance = pgTable("credit_balance", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  balance: integer("balance").default(0).notNull(),
  /** Fractions of a credit owed for tiny costs (MARYX's own jobs), taken once they add up to whole credits. */
  carry: doublePrecision("carry").default(0).notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

/**
 * Credits added to a balance. The id names where they came from
 * ("yookassa:<payment>", "stripe:<checkout session>", "promo:<code>:<user>",
 * "admin:<uuid>"), so a purchase is credited once however often it's reported.
 */
export const creditGrant = pgTable(
  "credit_grant",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    credits: integer("credits").notNull(),
    source: text("source").$type<"yookassa" | "stripe" | "paddle" | "paypal" | "ton" | "promo" | "admin" | "welcome">().notNull(),
    note: text("note"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (t) => [index("credit_grant_user_idx").on(t.userId, t.createdAt)],
);

/** A user's own OpenRouter key (BYOK), encrypted with the server's secret. */
export const userKey = pgTable("user_key", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  /** AES-256-GCM: "v1.<iv>.<tag>.<ciphertext>", base64url. */
  secret: text("secret").notNull(),
  /** The last characters, to show which key is saved. */
  hint: text("hint").notNull(),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});
